insert into public.company_settings (id,data,updated_at) values (1,'{"name":"Retro Clothing","tagline":"Luxury Made Affordable","since":"2026","address":"33/A Mela Mount Road, Rajiv Gandhi Nagar, Valukodai, Town, Tirunelveli, Tamil Nadu – 627006","district":"Tirunelveli, Tamil Nadu","pincode":"627006","phone1":"8667873216","phone2":"7358274739","whatsapp":"918667873216","email":"hello@retroclothing.in","instagram":"https://instagram.com/retroclothing","mapsUrl":"https://www.google.com/maps/place/8%C2%B043''47.2%22N+77%C2%B040''45.1%22E/@8.7297747,77.6766274,17z","founder":{"name":"Balaji","image":"https://picsum.photos/seed/founder/600/700"},"cofounder":{"name":"Surya Perumal","image":"https://picsum.photos/seed/cofounder/600/700"},"storyShort":"Born on the streets of Tirunelveli, Retro Clothing started as a pop-up cart with one idea — timeless silhouettes shouldn''t cost a fortune. Every piece we cut carries that promise forward.","storyLong":"Retro Clothing began in 2026 as Tirunelveli''s first aesthetic clothing cart — a single folding table, a rail of shirts, and a stubborn belief that small-town India deserved fashion with real intention behind it. What started as a weekend pop-up on Mela Mount Road grew into a full wardrobe label built on the same principle: cut fabric like it matters, price it like it''s for everyone. Today Retro Clothing ships across India, but the process hasn''t changed — every piece is still designed, checked and packed by hand from our Tirunelveli workshop, for people who want luxury without the luxury markup.","shopTiming":"Open Daily · 10:00 AM – 9:00 PM","deliveryInfo":"Dispatched from Tirunelveli within 24 hours. Delivery in 1–6 working days depending on your pincode."}',now()) on conflict (id) do update set data=excluded.data,updated_at=now();
